#!/data/data/com.termux/files/usr/bin/env bash
# nebula — cloud features on Firebase Realtime Database (REST): bug reports and online games.
# The connection settings are not stored as plain text: they live scrambled in assets/cloud/*.dat
# (see tools/pack-cloud.py). That hides them from casual reading only — protect the data itself with
# the security rules in docs/RTDB_RULES.json.

# BEGIN-PACK (generated by tools/pack-cloud.py, do not edit)
CLOUD_SEQ=(c4bc f730 5943 fd79 b615)
CLOUD_KF=(5e3a227a1f0bf992 d46fe1165d519ee3 e79f0a7504f4d3c1 0680bd9d8e8f5ed4)
CLOUD_KO=(1 0 2 3)
# END-PACK

CLOUD_DB=""; CLOUD_KEY=""; CLOUD_PROJECT=""; CLOUD_BODY=""; CLOUD_CODE=0

# cloud::cfg → sets CLOUD_DB / CLOUD_KEY / CLOUD_PROJECT (rebuilt from the chunks, kept in memory only)
cloud::cfg() {
  [[ -n $CLOUD_DB ]] && return 0
  if [[ -n ${NEBULA_CLOUD_DB:-} ]]; then CLOUD_DB=${NEBULA_CLOUD_DB%/}; CLOUD_KEY=${NEBULA_CLOUD_KEY:-test}; CLOUD_PROJECT=test; return 0; fi
  (( ${#CLOUD_SEQ[@]} )) || return 1
  local f blob="" hex="" i ch out=""; local -a kb=() db=() L=()
  for f in "${CLOUD_SEQ[@]}"; do [[ -f $NEBULA_HOME/assets/cloud/$f.dat ]] || return 1; blob+=$(<"$NEBULA_HOME/assets/cloud/$f.dat"); done
  for i in "${CLOUD_KO[@]}"; do hex+=${CLOUD_KF[i]}; done
  for ((i=0;i<${#hex};i+=2)); do kb+=($((16#${hex:i:2}))); done
  (( ${#kb[@]} )) || return 1
  db=($(printf '%s' "$blob" | base64 -d 2>/dev/null | od -An -v -tu1))
  for ((i=0;i<${#db[@]};i++)); do printf -v ch '\\x%02x' $(( db[i] ^ kb[i % ${#kb[@]}] )); out+=$ch; done
  out=$(printf '%b' "$out")
  mapfile -t L <<<"$out"
  [[ ${L[0]:-} == NCFG1 && -n ${L[1]:-} && -n ${L[2]:-} ]] || return 1
  CLOUD_DB=${L[1]%/}; CLOUD_KEY=${L[2]}; CLOUD_PROJECT=${L[3]:-}
}

cloud::j() { sed -n 's/.*"'"$1"'" *: *"\([^"]*\)".*/\1/p' <<<"$2" | head -1; }   # cloud::j key json → string value
cloud::esc() {
  local s=$1; s=${s//\\/\\\\}; s=${s//\"/\\\"}; s=${s//$'\n'/\\n}; s=${s//$'\t'/\\t}; s=${s//$'\r'/}
  printf '%s' "$s" | tr -d '\000-\010\013-\037'
}

# anonymous sign-in (so your rules can require "auth != null"); falls back to no token if it is switched off
cloud::token() {
  [[ -n ${NEBULA_CLOUD_NOAUTH:-} ]] && return 0
  local f="$NEBULA_CFG/cloud.tok" now exp=0 tok="" rt="" r
  now=$(date +%s)
  [[ -f $f ]] && IFS='|' read -r exp tok rt < "$f"
  if (( ${exp:-0} > now )); then printf '%s' "${tok:-}"; return 0; fi
  local idurl=${NEBULA_CLOUD_IDURL:-https://identitytoolkit.googleapis.com} tkurl=${NEBULA_CLOUD_TOKURL:-https://securetoken.googleapis.com}
  tok=""
  if [[ -n $rt ]]; then
    r=$(curl -sS --max-time 15 -X POST "$tkurl/v1/token?key=$CLOUD_KEY" -d "grant_type=refresh_token&refresh_token=$rt" 2>/dev/null)
    tok=$(cloud::j id_token "$r"); [[ -n $tok ]] && rt=$(cloud::j refresh_token "$r")
  fi
  if [[ -z $tok ]]; then
    r=$(curl -sS --max-time 15 -X POST -H 'Content-Type: application/json' -d '{"returnSecureToken":true}' "$idurl/v1/accounts:signUp?key=$CLOUD_KEY" 2>/dev/null)
    tok=$(cloud::j idToken "$r"); rt=$(cloud::j refreshToken "$r")
  fi
  mkdir -p "$NEBULA_CFG"
  if [[ -n $tok ]]; then ( umask 077; printf '%s|%s|%s\n' "$((now+3300))" "$tok" "$rt" > "$f" ); printf '%s' "$tok"
  else ( umask 077; printf '%s||\n' "$((now+600))" > "$f" ); fi   # no auth available: do not retry for 10 minutes
  return 0
}

# cloud::req METHOD path [json] → body in CLOUD_BODY, HTTP status in CLOUD_CODE; returns 0 on 2xx
cloud::req() {
  local m=$1 path=$2 body=${3:-} tok q="" out
  cloud::cfg || { CLOUD_CODE=0; CLOUD_BODY="not configured"; return 2; }
  tok=$(cloud::token); [[ -n $tok ]] && q="?auth=$tok"
  local -a a=(-sS --max-time 15 -X "$m" -w $'\n%{http_code}')
  [[ -n $body ]] && a+=(-H 'Content-Type: application/json' -d "$body")
  out=$(curl "${a[@]}" "$CLOUD_DB/$path.json$q" 2>&1) || { CLOUD_CODE=0; CLOUD_BODY=$out; return 1; }
  CLOUD_CODE=${out##*$'\n'}; CLOUD_BODY=${out%$'\n'*}
  [[ $CLOUD_CODE == 2* ]]
}

cloud::explain() {   # friendly reason for the last failure
  case $CLOUD_CODE in
    0)   ui::say_status ERR "Can't reach the server. Check your internet connection." ;;
    401|403) ui::say_status ERR "The server refused this (security rules). The owner needs to publish docs/RTDB_RULES.json." ;;
    404) ui::say_status ERR "The database wasn't found. Check the packed settings (tools/pack-cloud.py)." ;;
    *)   ui::say_status ERR "Server error ($CLOUD_CODE)." ;;
  esac
}

# ── bug report ───────────────────────────────────────────────────────────
cmd::report() {
  local msg="$*" f="$NEBULA_CFG/.report_ts" now last=0
  cloud::cfg || { ui::say_status ERR "Reporting isn't set up in this build."; return 1; }
  if [[ -z $msg ]]; then
    [[ -t 0 ]] || { ui::say_status WARN "Usage: report <what went wrong>"; return 1; }
    read -r -p "  What went wrong, or what would you like? " msg || return 1
  fi
  [[ -n ${msg//[[:space:]]/} ]] || { ui::say_status WARN "Nothing to send."; return 1; }
  (( ${#msg} > 800 )) && { msg=${msg:0:800}; ui::say_status INFO "Trimmed to 800 characters."; }
  now=$(date +%s); [[ -f $f ]] && last=$(<"$f"); last=${last:-0}
  (( now - last < 60 )) && { ui::say_status WARN "Please wait a minute between reports."; return 1; }
  local ver android model arch
  ver=$(<"$NEBULA_HOME/VERSION" 2>/dev/null); android=$(getprop ro.build.version.release 2>/dev/null); model=$(getprop ro.product.model 2>/dev/null); arch=$(uname -m 2>/dev/null)
  printf '\n  %sThis will be sent to the Nebula developer:%s\n' "$C_BOLD" "$C_RESET"
  printf '    message  %s\n    nebula   %s · android %s · %s · %s\n    %sNothing else (no files, no account details).%s\n\n' "$msg" "${ver:-?}" "${android:-?}" "${model:-?}" "${arch:-?}" "$C_DIM" "$C_RESET"
  ui::confirm "Send it?" Y || { ui::say_status INFO "Cancelled."; return 0; }
  local json
  json=$(printf '{"msg":"%s","ver":"%s","android":"%s","model":"%s","arch":"%s","ts":{".sv":"timestamp"}}' \
    "$(cloud::esc "$msg")" "$(cloud::esc "${ver:-}")" "$(cloud::esc "${android:-}")" "$(cloud::esc "${model:-}")" "$(cloud::esc "${arch:-}")")
  if cloud::req POST nebula/reports "$json"; then
    printf '%s\n' "$now" > "$f"
    ui::say_status OK "Sent. Thank you! (id $(cloud::j name "$CLOUD_BODY"))"
  else cloud::explain; return 1; fi
}

# ── online tic-tac-toe ───────────────────────────────────────────────────
vs::win() {   # board → X | O | draw | ""
  local b=$1 l a c d
  for l in "0 1 2" "3 4 5" "6 7 8" "0 3 6" "1 4 7" "2 5 8" "0 4 8" "2 4 6"; do
    set -- $l; a=${b:$1:1}; c=${b:$2:1}; d=${b:$3:1}
    [[ $a != - && $a == "$c" && $a == "$d" ]] && { printf '%s' "$a"; return; }
  done
  [[ $b != *-* ]] && printf 'draw'
}
vs::draw() {   # board cursor me turn winner note
  local b=$1 cur=$2 me=$3 turn=$4 win=$5 note=$6 i r s ch
  g::ln "${C_BOLD}Versus${C_RESET}  you are ${C_BOLD}$me${C_RESET}   ${C_DIM}room $VS_CODE${C_RESET}"
  g::ln "${C_DIM}arrows + enter (or 1-9) · q leaves${C_RESET}"; g::ln ""
  for r in 0 1 2; do
    s="   "
    for i in $((r*3)) $((r*3+1)) $((r*3+2)); do
      ch=${b:i:1}; local cell=" · "
      [[ $ch == X ]] && cell=" ${FGC[51]}X${C_RESET} "; [[ $ch == O ]] && cell=" ${FGC[221]}O${C_RESET} "
      (( i == cur )) && [[ -z $win ]] && cell=$'\033[7m'"$cell"$'\033[0m'
      s+="$cell"; (( i % 3 < 2 )) && s+="│"
    done
    g::ln "$s"; (( r < 2 )) && g::ln "   ───┼───┼───"
  done
  g::ln ""; g::ln "  $note"; g::paint
}

game::versus() {
  cloud::cfg || { ui::say_status ERR "Online play isn't set up in this build."; return 1; }
  mkdir -p "$GAME_DIR"
  local mode=${1:-} VS_CODE=${2:-} me other idf="$GAME_DIR/versus.id" myid
  [[ -s $idf ]] || printf '%04x%04x\n' "$RANDOM" "$RANDOM" > "$idf"; myid=$(<"$idf")
  if [[ -z $mode ]]; then
    printf '\033[?25h\033[H\033[2J%sVersus%s  tic-tac-toe over the internet\n\n  1  Host a game (you get a room code)\n  2  Join a friend (enter their code)\n\n' "$C_BOLD" "$C_RESET"
    local p; IFS= read -r -p "  1 or 2: " p || return; [[ $p == 2 ]] && mode=join || mode=host
    printf '\033[?25l'
  fi
  case $mode in
    host)
      local abc=ABCDEFGHJKMNPQRSTUVWXYZ23456789 i; VS_CODE=""; for i in 1 2 3 4; do VS_CODE+=${abc:RANDOM%${#abc}:1}; done
      if ! cloud::req PUT "nebula/rooms/$VS_CODE" "{\"board\":\"---------\",\"turn\":\"X\",\"winner\":\"\",\"x\":\"$myid\",\"o\":\"\",\"ts\":{\".sv\":\"timestamp\"}}"; then cloud::explain; g::wait; return 1; fi
      me=X; other=O
      local waited=0
      while :; do
        printf '\033[H\033[2J%sVersus%s\n\n  Room code: %s%s%s\n  Tell your friend: Nebula → game → Versus → Join → this code.\n\n  %sWaiting for them… (q cancels)%s\n' "$C_BOLD" "$C_RESET" "$C_GREEN$C_BOLD" "$VS_CODE" "$C_RESET" "$C_DIM" "$C_RESET"
        cloud::req GET "nebula/rooms/$VS_CODE" && [[ -n $(cloud::j o "$CLOUD_BODY") ]] && break
        g::key 2 && [[ $K == q ]] && { cloud::req DELETE "nebula/rooms/$VS_CODE"; return; }
        waited=$((waited+1)); (( waited > 150 )) && { ui::say_status WARN "Nobody joined."; cloud::req DELETE "nebula/rooms/$VS_CODE"; g::wait; return; }
      done ;;
    join)
      if [[ -z $VS_CODE ]]; then printf '\033[?25h'; IFS= read -r -p "  room code: " VS_CODE || return; printf '\033[?25l'; fi
      VS_CODE=${VS_CODE^^}; [[ $VS_CODE =~ ^[A-Z0-9]{4}$ ]] || { ui::say_status ERR "A room code is 4 letters/digits."; g::wait; return 1; }
      cloud::req GET "nebula/rooms/$VS_CODE" || { cloud::explain; g::wait; return 1; }
      [[ $CLOUD_BODY == null ]] && { ui::say_status ERR "No room $VS_CODE. Check the code."; g::wait; return 1; }
      [[ -n $(cloud::j o "$CLOUD_BODY") ]] && { ui::say_status ERR "That room is already full."; g::wait; return 1; }
      cloud::req PATCH "nebula/rooms/$VS_CODE" "{\"o\":\"$myid\"}" || { cloud::explain; g::wait; return 1; }
      me=O; other=X ;;
    *) ui::say_status ERR "Usage: game versus [host|join CODE]"; return 1 ;;
  esac
  local board turn win cur=4 note last="" VS_MYTURN=0 idx nb nt w
  while :; do
    if ! cloud::req GET "nebula/rooms/$VS_CODE"; then note="${C_YELLOW}connection hiccup, retrying…${C_RESET}"; sleep 1; continue; fi
    [[ $CLOUD_BODY == null ]] && { g::ln ""; ui::say_status INFO "The room was closed."; g::wait; return; }
    board=$(cloud::j board "$CLOUD_BODY"); turn=$(cloud::j turn "$CLOUD_BODY"); win=$(cloud::j winner "$CLOUD_BODY")
    [[ ${#board} -eq 9 ]] || board="---------"
    if [[ -n $win ]]; then
      case $win in
        "$me") note="${C_GREEN}${C_BOLD}You win!${C_RESET}" ;;
        draw)  note="${C_YELLOW}Draw.${C_RESET}" ;;
        left*) note="${C_YELLOW}Your friend left.${C_RESET}" ;;
        *)     note="${C_RED}You lost.${C_RESET}" ;;
      esac
      vs::draw "$board" "$cur" "$me" "$turn" "$win" "$note"; [[ $mode == host ]] && cloud::req DELETE "nebula/rooms/$VS_CODE"; g::wait; return
    fi
    if [[ $turn == "$me" ]]; then
      VS_MYTURN=1; note="${C_GREEN}Your turn${C_RESET}"
      vs::draw "$board" "$cur" "$me" "$turn" "" "$note"
      g::key; g::norm; idx=-1
      case $K in
        left)  (( cur % 3 > 0 )) && cur=$((cur-1)) ;;  right) (( cur % 3 < 2 )) && cur=$((cur+1)) ;;
        up)    (( cur >= 3 )) && cur=$((cur-3)) ;;      down)  (( cur < 6 )) && cur=$((cur+3)) ;;
        enter|space) idx=$cur ;;
        [1-9]) idx=$((K-1)); cur=$idx ;;
        q|esc) cloud::req PATCH "nebula/rooms/$VS_CODE" "{\"winner\":\"left$me\"}"; return ;;
      esac
      if (( idx >= 0 )) && [[ ${board:idx:1} == - ]]; then
        nb="${board:0:idx}$me${board:idx+1}"; nt=$other; w=$(vs::win "$nb")
        cloud::req PATCH "nebula/rooms/$VS_CODE" "{\"board\":\"$nb\",\"turn\":\"$nt\",\"winner\":\"$w\"}" || { cloud::explain; sleep 1; }
      fi
    else
      VS_MYTURN=0
      if [[ $board$turn != "$last" ]]; then vs::draw "$board" "$cur" "$me" "$turn" "" "${C_DIM}$other is thinking…${C_RESET}"; last=$board$turn; fi
      if g::key 1.2; then [[ $K == q ]] && { cloud::req PATCH "nebula/rooms/$VS_CODE" "{\"winner\":\"left$me\"}"; return; }; fi
    fi
  done
}
